# ── configure() with interactive rendering ───────────────────────────────────


def test_configure_axis_interactive_no_crash():
    """configure_axis must not crash the interactive rendering pipeline."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure_axis(label_font_size=14, tick_size=10)
    )
    scene, _ = _scene(chart)
    assert len(scene["panels"]) >= 1


def test_configure_title_interactive_preserves_title():
    """configure_title properties must flow through to the interactive scene."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .properties(title="My Title")
        .configure_title(font_size=20, font_weight="bold")
    )
    scene, _ = _scene(chart)
    title_nodes = scene.get("title", [])
    assert len(title_nodes) > 0, "configured title must appear in interactive scene"


