# ── Degenerate / empty inputs through interactive ────────────────────────────


def test_zero_row_df_interactive_produces_empty_panels():
    """Zero-row DataFrame must produce a scene with empty panels list."""
    df = pl.DataFrame(
        {
            "x": pl.Series([], dtype=pl.Float64),
            "y": pl.Series([], dtype=pl.Float64),
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene_json, packed = _render_scene(chart)
    scene = json.loads(scene_json)
    assert isinstance(scene["panels"], list)
    assert len(scene["panels"]) == 0
    # Width/height must not be NaN
    w, h = scene["width"], scene["height"]
    assert w == w, "width must not be NaN"
    assert h == h, "height must not be NaN"


def test_single_row_df_interactive_scene_no_nan():
    """Single-row DataFrame must produce a scene with no NaN in coordinates."""
    df = pl.DataFrame({"x": [42.0], "y": [7.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene_json, _ = _render_scene(chart)
    assert "NaN" not in scene_json
    assert "Infinity" not in scene_json


def test_all_identical_values_interactive_no_nan():
    """All-identical data (collapsed domain) must not produce NaN in scene."""
    df = pl.DataFrame({"x": [5.0] * 10, "y": [3.0] * 10})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene_json, _ = _render_scene(chart)
    assert "NaN" not in scene_json


