# ── HTML save edge cases ────────────────────────────────────────────────────


def test_interactive_save_produces_html():
    """InteractiveChart.save() must produce a valid HTML file with valid scene JSON."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y")
    )
    with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
        ic.save(f.name)
        html = open(f.name).read()
    assert "<html" in html.lower() or "<!doctype" in html.lower()
    # Check that the scene JSON embedded in the HTML does not contain NaN
    # (the D3 JavaScript library legitimately contains "NaN" in its code)
    assert "NaN" not in ic.scene_json, "scene JSON must not contain literal NaN"


def test_interactive_save_zero_row_df_no_crash():
    """InteractiveChart.save() with zero-row DataFrame must not crash."""
    df = pl.DataFrame(
        {
            "x": pl.Series([], dtype=pl.Float64),
            "y": pl.Series([], dtype=pl.Float64),
        }
    )
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y")
    )
    with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
        ic.save(f.name)
        html = open(f.name).read()
    assert len(html) > 0


def test_interactive_save_toolbar_false():
    """InteractiveChart.save() with toolbar=False must produce valid HTML."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y"),
        toolbar=False,
    )
    with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
        ic.save(f.name)
        html = open(f.name).read()
    assert len(html) > 0


# ── Composition corners with interactive ─────────────────────────────────────


def test_layer_merge_interactive_no_crash():
    """Layered chart (Chart + Chart = merged Chart) must render via _render_scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_line().encode(x="x", y="y")
    layered = c1 + c2
    # Chart + Chart merges into a single Chart (no _render_interactive)
    scene_json, _ = _render_scene(layered)
    scene = json.loads(scene_json)
    assert "panels" in scene


def test_hconcat_interactive_no_crash():
    """HConcat composition must render interactively without crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_bar().encode(x="x", y="y")
    concat = c1 | c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    assert "panels" in scene


def test_vconcat_interactive_no_crash():
    """VConcat composition must render interactively without crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_bar().encode(x="x", y="y")
    concat = c1 & c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    assert "panels" in scene


def test_layer_merge_with_annotation_interactive():
    """Merged layer + annotation must render via _render_scene without crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    layered = (
        fr.Chart(df).mark_point().encode(x="x", y="y")
        + fr.Chart(df).mark_line().encode(x="x", y="y")
        + fr.annotate_hline(y=3.0, stroke="red")
    )
    # This goes through _render_scene → Rust render_interactive
    scene_json, _ = _render_scene(layered)
    scene = json.loads(scene_json)
    assert "panels" in scene


# ── Large dataset → packed binary path ───────────────────────────────────────


def test_large_dataset_produces_packed_data():
    """2000+ row dataset must produce non-empty packed binary data."""
    import numpy as np

    rng = np.random.default_rng(42)
    n = 2000
    df = pl.DataFrame(
        {"x": rng.uniform(0, 100, n).tolist(), "y": rng.uniform(0, 100, n).tolist()}
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    _, packed = _render_scene(chart)
    assert len(packed) > 0, "2000-row dataset must produce packed binary sidecar"


# ── Selection spec round-trip ────────────────────────────────────────────────


def test_selection_point_spec_in_scene_json():
    """Point selection must appear in the scene JSON selections list."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    sel = fr.selection_point(name="my_sel")
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").add_selection(sel)
    scene, _ = _scene(chart)
    sels = scene.get("selections", [])
    names = [s.get("name", "") for s in sels]
    assert "my_sel" in names, f"'my_sel' not in selections; got {names}"


def test_selection_interval_spec_in_scene_json():
    """Interval selection must appear in scene JSON."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    sel = fr.selection_interval(name="brush")
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").add_selection(sel)
    scene, _ = _scene(chart)
    sels = scene.get("selections", [])
    names = [s.get("name", "") for s in sels]
    assert "brush" in names


# ── Scene JSON contract pins ────────────────────────────────────────────────


def test_panel_plot_area_dimensions_non_negative():
    """Plot area w/h must be >= 0 (not NaN or negative)."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    for panel in scene["panels"]:
        pa = panel["plot_area"]
        assert pa["w"] >= 0, f"plot_area width must be >= 0, got {pa['w']}"
        assert pa["h"] >= 0, f"plot_area height must be >= 0, got {pa['h']}"


def test_scene_width_height_match_viewport():
    """Scene width/height must be positive and reasonable."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    assert scene["width"] > 0
    assert scene["height"] > 0
    assert scene["width"] < 1e6, "width must be reasonable"
    assert scene["height"] < 1e6, "height must be reasonable"


# ── Tooltip presence with auto_tooltips=True ─────────────────────────────────


def test_auto_tooltips_present_for_small_dataset():
    """Auto-tooltips must populate tooltip data for small datasets."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    if len(scene["panels"]) > 0:
        marks = scene["panels"][0]["marks"]
        if len(marks) > 0:
            tooltips = marks[0].get("tooltips")
            if tooltips is not None:
                assert len(tooltips) > 0, "auto tooltips should be non-empty"


# ── Interaction config in scene ──────────────────────────────────────────────


def test_interaction_config_key_in_scene():
    """Scene JSON must contain an 'interaction' key."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    assert "interaction" in scene, "scene must contain 'interaction' config"


def test_toolbar_false_propagates():
    """toolbar=False must be accessible in the interaction config."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y"),
        toolbar=False,
    )
    config_json = ic._build_interaction_config(ic.scene_json)
    config = json.loads(config_json)
    assert config.get("toolbar") is False, "toolbar must be False in config"


def test_toolbar_true_propagates():
    """toolbar=True (default) must be accessible in the interaction config."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y"),
        toolbar=True,
    )
    config_json = ic._build_interaction_config(ic.scene_json)
    config = json.loads(config_json)
    assert config.get("toolbar") is True


# ── Coord system with interactive ────────────────────────────────────────────


def test_coord_cartesian_xlim_interactive():
    """CoordCartesian with xlim must produce valid interactive scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .coord(fr.CoordCartesian(xlim=(0.0, 5.0)))
    )
    scene, _ = _scene(chart)
    assert len(scene["panels"]) >= 1


def test_coord_fixed_interactive():
    """CoordFixed must produce valid interactive scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .coord(fr.CoordFixed(ratio=1.0))
    )
    scene, _ = _scene(chart)
    assert len(scene["panels"]) >= 1


# ── _repr_mimebundle_ ────────────────────────────────────────────────────────


def test_repr_mimebundle_returns_dict_or_none():
    """_repr_mimebundle_ must return a dict (with anywidget) or None (without)."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    ic = InteractiveChart(
        fr.Chart(df).mark_point().encode(x="x", y="y")
    )
    result = ic._repr_mimebundle_()
    # With anywidget installed: returns (dict, dict) tuple from widget
    # Without anywidget: returns None
    assert result is None or isinstance(result, (dict, tuple)), (
        f"_repr_mimebundle_ must return None or dict/tuple, got {type(result)}"
    )
